-- Comissões, Metas e Controladoria Comercial
create table if not exists public.erp_comissao_perfis (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id) on delete restrict,nome text not null,ativo boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(empresa_id,nome));
create table if not exists public.erp_comissao_regras (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id) on delete restrict,perfil_id uuid not null references public.erp_comissao_perfis(id) on delete cascade,produto_id uuid not null references public.erp_produtos(id) on delete restrict,percentual numeric(8,4) not null check(percentual between 0 and 100),meta_quantidade numeric(18,6) not null default 0 check(meta_quantidade>=0),ativo boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(empresa_id,perfil_id,produto_id));
create table if not exists public.erp_comissao_vinculos (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id) on delete restrict,usuario_id uuid not null references public.erp_usuarios(id) on delete cascade,perfil_id uuid not null references public.erp_comissao_perfis(id) on delete restrict,status text not null default 'Ativo' check(status in ('Ativo','Inativo')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(empresa_id,usuario_id));
create table if not exists public.erp_comissao_calculos (id uuid primary key default gen_random_uuid(),empresa_id uuid not null references public.erp_empresas(id) on delete restrict,competencia date not null,usuario_id uuid references public.erp_usuarios(id) on delete set null,meta_faturamento numeric(18,2) not null default 0,total_vendas numeric(18,2) not null default 0,total_comissao numeric(18,2) not null default 0,meta_atingida boolean not null default false,calculado_por uuid references public.erp_usuarios(id) on delete set null,created_at timestamptz not null default now());
create table if not exists public.erp_comissao_linhas (id uuid primary key default gen_random_uuid(),calculo_id uuid not null references public.erp_comissao_calculos(id) on delete cascade,empresa_id uuid not null references public.erp_empresas(id) on delete restrict,pedido_id uuid not null references public.erp_pedidos_venda(id) on delete restrict,item_id uuid not null references public.erp_pedidos_venda_itens(id) on delete restrict,produto_id uuid not null references public.erp_produtos(id) on delete restrict,usuario_id uuid references public.erp_usuarios(id) on delete set null,quantidade numeric(18,6) not null,valor_total numeric(18,2) not null,percentual numeric(8,4) not null,comissao_liquida numeric(18,2) not null,created_at timestamptz not null default now());
create index if not exists erp_comissao_regras_empresa_idx on public.erp_comissao_regras(empresa_id,perfil_id,ativo);
create index if not exists erp_comissao_vinculos_empresa_idx on public.erp_comissao_vinculos(empresa_id,status);
create index if not exists erp_comissao_calculos_empresa_comp_idx on public.erp_comissao_calculos(empresa_id,competencia);
create index if not exists erp_comissao_linhas_calculo_idx on public.erp_comissao_linhas(calculo_id);
alter table public.erp_comissao_perfis enable row level security; alter table public.erp_comissao_regras enable row level security; alter table public.erp_comissao_vinculos enable row level security; alter table public.erp_comissao_calculos enable row level security; alter table public.erp_comissao_linhas enable row level security;
drop policy if exists erp_comissao_perfis_tenant on public.erp_comissao_perfis; create policy erp_comissao_perfis_tenant on public.erp_comissao_perfis for all to authenticated using(public.erp_is_master() or empresa_id=public.erp_current_empresa_id()) with check(public.erp_is_master() or empresa_id=public.erp_current_empresa_id());
drop policy if exists erp_comissao_regras_tenant on public.erp_comissao_regras; create policy erp_comissao_regras_tenant on public.erp_comissao_regras for all to authenticated using(public.erp_is_master() or empresa_id=public.erp_current_empresa_id()) with check(public.erp_is_master() or empresa_id=public.erp_current_empresa_id());
drop policy if exists erp_comissao_vinculos_tenant on public.erp_comissao_vinculos; create policy erp_comissao_vinculos_tenant on public.erp_comissao_vinculos for all to authenticated using(public.erp_is_master() or empresa_id=public.erp_current_empresa_id()) with check(public.erp_is_master() or empresa_id=public.erp_current_empresa_id());
drop policy if exists erp_comissao_calculos_tenant on public.erp_comissao_calculos; create policy erp_comissao_calculos_tenant on public.erp_comissao_calculos for all to authenticated using(public.erp_is_master() or empresa_id=public.erp_current_empresa_id()) with check(public.erp_is_master() or empresa_id=public.erp_current_empresa_id());
drop policy if exists erp_comissao_linhas_tenant on public.erp_comissao_linhas; create policy erp_comissao_linhas_tenant on public.erp_comissao_linhas for all to authenticated using(public.erp_is_master() or empresa_id=public.erp_current_empresa_id()) with check(public.erp_is_master() or empresa_id=public.erp_current_empresa_id());
create or replace function public.erp_comissao_autorizado() returns boolean language sql stable security invoker set search_path=public as $$ select public.erp_is_master() or exists(select 1 from public.erp_usuarios u where u.auth_user_id=auth.uid() and u.ativo=true and u.deleted_at is null and upper(trim(coalesce(u.perfil,''))) in ('ADMINISTRADOR','COMERCIAL','CONTROLADORIA','MASTER')); $$;
create or replace function public.erp_comissao_salvar_regra(p_perfil_id uuid,p_produto_id uuid,p_percentual numeric,p_meta_quantidade numeric) returns public.erp_comissao_regras language plpgsql security invoker set search_path=public as $$ declare v_empresa uuid:=public.erp_current_empresa_id();v public.erp_comissao_regras;begin if not public.erp_comissao_autorizado() then raise exception 'COMISSOES_NAO_AUTORIZADO';end if;if v_empresa is null then raise exception 'EMPRESA_NAO_IDENTIFICADA';end if;insert into public.erp_comissao_regras(empresa_id,perfil_id,produto_id,percentual,meta_quantidade) values(v_empresa,p_perfil_id,p_produto_id,p_percentual,p_meta_quantidade) on conflict(empresa_id,perfil_id,produto_id) do update set percentual=excluded.percentual,meta_quantidade=excluded.meta_quantidade,ativo=true,updated_at=now() returning * into v;return v;end; $$;
create or replace function public.erp_comissao_vincular(p_usuario_id uuid,p_perfil_id uuid,p_status text) returns public.erp_comissao_vinculos language plpgsql security invoker set search_path=public as $$ declare v_empresa uuid:=public.erp_current_empresa_id();v public.erp_comissao_vinculos;begin if not public.erp_comissao_autorizado() then raise exception 'COMISSOES_NAO_AUTORIZADO';end if;if v_empresa is null then raise exception 'EMPRESA_NAO_IDENTIFICADA';end if;insert into public.erp_comissao_vinculos(empresa_id,usuario_id,perfil_id,status) values(v_empresa,p_usuario_id,p_perfil_id,p_status) on conflict(empresa_id,usuario_id) do update set perfil_id=excluded.perfil_id,status=excluded.status,updated_at=now() returning * into v;return v;end; $$;
create or replace function public.erp_comissao_calcular(p_competencia date,p_usuario_id uuid default null,p_meta_faturamento numeric default 0) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_empresa uuid:=public.erp_current_empresa_id();v_calc uuid;v_total numeric:=0;v_comissao numeric:=0;v_meta numeric:=coalesce(p_meta_faturamento,0);v_count integer:=0;begin if not public.erp_comissao_autorizado() then raise exception 'COMISSOES_NAO_AUTORIZADO';end if;if v_empresa is null then raise exception 'EMPRESA_NAO_IDENTIFICADA';end if;insert into public.erp_comissao_calculos(empresa_id,competencia,usuario_id,meta_faturamento,calculado_por) select v_empresa,date_trunc('month',p_competencia)::date,p_usuario_id,v_meta,u.id from public.erp_usuarios u where u.auth_user_id=auth.uid() and u.ativo=true limit 1 returning id into v_calc;insert into public.erp_comissao_linhas(calculo_id,empresa_id,pedido_id,item_id,produto_id,usuario_id,quantidade,valor_total,percentual,comissao_liquida) select v_calc,p.empresa_id,p.id,i.id,i.produto_id,u.id,i.quantidade,coalesce(i.total,i.quantidade*i.valor_unitario*(1-coalesce(i.desconto,0)/100)),coalesce(r.percentual,0),round(coalesce(i.total,i.quantidade*i.valor_unitario*(1-coalesce(i.desconto,0)/100))*coalesce(r.percentual,0)/100,2) from public.erp_pedidos_venda p join public.erp_pedidos_venda_itens i on i.pedido_id=p.id and i.empresa_id=p.empresa_id join public.erp_usuarios u on u.empresa_id=p.empresa_id and u.ativo=true and u.deleted_at is null join public.erp_comissao_vinculos v on v.empresa_id=p.empresa_id and v.usuario_id=u.id and v.status='Ativo' join public.erp_comissao_regras r on r.empresa_id=p.empresa_id and r.perfil_id=v.perfil_id and r.produto_id=i.produto_id and r.ativo=true where p.empresa_id=v_empresa and (p_usuario_id is null or u.id=p_usuario_id) and p.data_entrada>=date_trunc('month',p_competencia)::date and p.data_entrada<(date_trunc('month',p_competencia)+interval '1 month')::date and lower(coalesce(p.status,'')) not in ('cancelado','cancelada','rascunho','aberto','cotação','cotacao');select coalesce(sum(valor_total),0),coalesce(sum(comissao_liquida),0),count(*) into v_total,v_comissao,v_count from public.erp_comissao_linhas where calculo_id=v_calc;update public.erp_comissao_calculos set total_vendas=v_total,total_comissao=v_comissao,meta_atingida=(v_total>=v_meta and v_meta>0) where id=v_calc;return jsonb_build_object('calculo_id',v_calc,'total_vendas',v_total,'total_comissao',v_comissao,'meta_atingida',(v_total>=v_meta and v_meta>0),'linhas',v_count);end; $$;
revoke all on function public.erp_comissao_autorizado() from public,anon; grant execute on function public.erp_comissao_autorizado() to authenticated;
revoke all on function public.erp_comissao_salvar_regra(uuid,uuid,numeric,numeric) from public,anon; grant execute on function public.erp_comissao_salvar_regra(uuid,uuid,numeric,numeric) to authenticated;
revoke all on function public.erp_comissao_vincular(uuid,uuid,text) from public,anon; grant execute on function public.erp_comissao_vincular(uuid,uuid,text) to authenticated;
revoke all on function public.erp_comissao_calcular(date,uuid,numeric) from public,anon; grant execute on function public.erp_comissao_calcular(date,uuid,numeric) to authenticated;